const remunerationInput = z.object({ remunerationMode: z.enum(["fixed", "commission", "fixed_plus_commission"]), fixedMonthlyCents: z.number().int().min(0), commissionBasis: z.enum(["revenue", "net_profit"]), rateBasisPoints: z.number().int().min(0).max(10000), active: z.boolean() });
const optionalLoginEmail = z.preprocess(value => typeof value === "string" && !value.trim() ? null : value, z.string().trim().email().max(320).nullable().optional());
const sellerInput = z.object({ name: z.string().trim().min(2).max(160), email: optionalLoginEmail, phone: z.string().trim().max(50).nullable().optional(), username: z.string().trim().min(3).max(80).regex(/^[a-zA-Z0-9._-]+$/), password: z.string().min(8).max(128), remuneration: remunerationInput, salarySchedule: salaryScheduleInput });
